"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 scoring (plan 7.1-7.5): metrics, operating points and intervals.

Decisions: per window (decision point) a system gives {"S": "stop"|"continue", "R": "respond"|"not"} (it is always
asked both where a user line ends during assistant speech; plan section 2). Only the scorer knows which are scored:
S where the gold S is set, R where the gold R is set.

Units: a group of versions (single-line parts) or an episode; a unit is right when every scored decision in it is
right. Parts: r_hear, r_react, s_react, s_move (group accuracy) and episode (whole-episode accuracy); the primary
metric is their unweighted mean. Floors (plan 4.6): share of right decisions per floor kind. Audio-decisive part
(plan 4.7): R-hear plus the S-move units whose visitor did not speak; the mean of the two accuracies. Unseen part
(plan 7.1): per part, the accuracy pooled over its unseen subsets, then the mean over those parts.

Intervals (plan 7.1): one-way cluster bootstraps (Poisson(1) weights per cluster, B replicates) by conversation, by
the attention-event recording group and by a second key group (the decoy in R-hear, the door in S-move; a singleton
elsewhere), combined by inclusion-exclusion over the three factors (Cameron, Gelbach and Miller), never below the
largest one-way variance; 95% interval = point +- 1.96 SE. calibrate() checks the method on simulated data with the
same structure (independent units: SE ratio 0.9-1.25; one-factor clustering: within 20%).
"""
import itertools
import json
from collections import defaultdict

import numpy as np

PARTS = ["r_hear", "r_react", "s_react", "s_move", "episode"]
MAIN_SUBSETS = (None,)
UNSEEN = ("test_only_phrase", "piper", "vibration", "new_rec", "prompt2")


def load_meta(path):
    return [json.loads(line) for line in open(path, encoding="utf-8")]


def window_ids(rows):
    return [(r["unit"], r["version"], p["k"]) for r in rows for p in r["points"]]


def load_groups(split):
    """{clip path: recording group} of a split, the table the renderer's caps and the leak check use."""
    import os
    import sys
    sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
    import p1v4_units as U
    return dict(U.Assets(split).group)


def excluded_units(path="results/step0_v04/excluded_units.json"):
    """Units not used for training, thresholds or scores (plan 8.4: TV speakers in the speaker-ID model's training
    data or without a name; scripts/step0v4_speaker_overlap.py)."""
    import os
    if not os.path.exists(path):
        return set()
    return {u for us in json.load(open(path, encoding="utf-8"))["units"].values() for u in us}


def unit_table(rows, decisions, groups, exclude=None):
    """{unit: {"part", "subset", "right": 0/1, "conv", "event", "second", "floor": kind or None, "audio": bool}}.
    decisions: {(unit, version, k): {"S": ..., "R": ...}}. groups: {clip path: recording group} (load_groups). The
    event and second factors are recording groups (plan 7.1), so the clips of one group share a cluster; a unit
    without such a recording is a cluster of its own. An episode's main event is its phone ring or its door sound (an
    episode has at most one of them). exclude: units left out (default: excluded_units())."""
    exclude = excluded_units() if exclude is None else exclude
    units = {}
    for r in rows:
        if r["unit"] in exclude:
            continue
        u = units.setdefault(r["unit"], {"part": r["part"], "subset": r["subset"], "ok": True, "rows": [],
                                         "spec": r["spec"], "points": []})
        u["rows"].append(r)
        for p in r["points"]:
            d = decisions.get((r["unit"], r["version"], p["k"]), {})
            g = p["gold"]
            ok_s = g.get("S") is None or d.get("S") == g["S"]
            ok_r = g.get("R") is None or d.get("R") == g["R"]
            u["points"].append((p, ok_s and ok_r))
            u["ok"] = u["ok"] and ok_s and ok_r
    out = {}
    for uid, u in units.items():
        s = u["spec"]
        clips = s.get("clips") or {}
        ev = s.get("event") or clips.get("ring") or clips.get("door_event")
        second = s.get("decoy") if u["part"] == "r_hear" else s.get("door") if u["part"] == "s_move" else None
        for path in (ev, second):
            if path and path not in groups:
                raise KeyError(f"{uid}: no recording group for {path}")
        out[uid] = {"part": u["part"], "subset": u["subset"], "right": int(u["ok"]), "spec": s,
                    "conv": f"{uid.split('_d')[0]}:{s.get('conv')}",
                    "event": groups[ev] if ev else f"none:{uid}",
                    "second": groups[second] if second else f"none:{uid}", "points": u["points"],
                    # background-noise recording and user voice (pre-freeze review 2026-11-16: reported as extra
                    # cluster factors for sensitivity; the plan's interval uses conv, event and second only)
                    "noise": s.get("noise") or f"none:{uid}",
                    "voice": json.dumps(s.get("user"), sort_keys=True) if s.get("user") else f"none:{uid}",
                    "floor": s.get("which") if u["part"] == "floor" else None,
                    "audio": u["part"] == "r_hear" or (u["part"] == "s_move" and not s.get("visitor_speaks"))}
    return out


def metrics(T):
    """Point estimates from a unit table (main subset only for the parts)."""
    acc = {}
    for p in PARTS:
        us = [u for u in T.values() if u["part"] == p and u["subset"] is None]
        acc[p] = float(np.mean([u["right"] for u in us])) if us else float("nan")
    m = {"parts": acc, "primary": float(np.mean([acc[p] for p in PARTS]))}
    fl = defaultdict(list)
    for u in T.values():
        if u["floor"]:
            fl[u["floor"].split("_")[0]] += [ok for _, ok in u["points"]]
    m["floors"] = {k: float(np.mean(v)) for k, v in fl.items()}
    m["floor_mean"] = float(np.mean(list(m["floors"].values()))) if m["floors"] else float("nan")
    au = [u["right"] for u in T.values() if u["audio"] and u["subset"] is None and u["part"] == "r_hear"]
    am = [u["right"] for u in T.values() if u["audio"] and u["subset"] is None and u["part"] == "s_move"]
    m["audio"] = float(np.mean([np.mean(au), np.mean(am)])) if au and am else float("nan")
    un = {}
    for p in PARTS:
        us = [u["right"] for u in T.values() if u["part"] == p and u["subset"] in UNSEEN]
        if us:
            un[p] = float(np.mean(us))
    m["unseen_parts"] = un
    m["unseen"] = float(np.mean(list(un.values()))) if un else float("nan")
    return m


def s_react_ring_split(rows, decisions):
    """Pre-specified diagnostic (author, 2026-11-14): S accuracy of the S-react phone versions 2 (keep going) and 3
    (listening sound), split by whether their ring stopped at the moment version 1's ring stopped or still rings at
    the decision point. A system that leans on the ring state does worse on the stopped half, where versions 2 and 3
    differ from version 1 only by the line. Returns {"ring_stopped"|"still_ringing": (accuracy, n)}."""
    acc = defaultdict(list)
    for r in rows:
        if r["part"] != "s_react" or r["subset"] is not None or r["version"] not in ("2", "3"):
            continue
        ev = next((s for s in r["sources"] if s["id"] == "ev"), None)
        if ev is None or ev.get("cls") != "phone":
            continue
        for p in r["points"]:
            if p["gold"].get("S") is None:
                continue
            d = decisions.get((r["unit"], r["version"], p["k"]), {})
            state = "still_ringing" if ev["end"] > p["t"] - 1e-3 else "ring_stopped"
            acc[state].append(int(d.get("S") == p["gold"]["S"]))
    return {k: (float(np.mean(v)), len(v)) for k, v in acc.items()}


PAUSE_RULE_S = 3.0      # pause-only rule for episode R, fitted on train draw 0 (best cut 3.04 s), fixed 2026-11-15


def line_pause(r, s):
    """Silence before user line s in episode row r: from the end of the last sound or assistant turn before it."""
    prev = [x["end"] for x in r["sources"] if x["end"] <= s["start"] + 1e-6 and x["id"] != s["id"]]
    prev += [a["end"] for a in r["assistant"] if a["end"] <= s["start"] + 1e-6]
    return s["start"] - max(prev) if prev else float("nan")


def episode_r_split(rows, decisions):
    """Pre-specified diagnostic (author, 2026-11-15): R accuracy on the episode user lines within each gold class, so a
    plain lean towards "respond" or "not" does not show up as a gap. Away from the door, by the pause before the line
    ("<gold>_pause_short" below PAUSE_RULE_S, "<gold>_pause_long" at or above it); at the door, "door_<gold>". A system
    that leans on the pause does worse on respond_pause_long than on respond_pause_short and worse on not_pause_short
    than on not_pause_long; one that leans on the door position does worse on door_respond than on the respond cells
    away from the door. Returns {cell: (accuracy, n)}."""
    acc = defaultdict(list)
    for r in rows:
        if r["part"] != "episode" or r["subset"] is not None:
            continue
        for p in r["points"]:
            g = p["gold"].get("R")
            if not p.get("line") or g is None:
                continue
            s = next(x for x in r["sources"] if x["id"] == p["line"])
            if s["pos"] == "door":
                cell = f"door_{g}"
            else:
                cell = f"{g}_pause_" + ("long" if line_pause(r, s) >= PAUSE_RULE_S else "short")
            d = decisions.get((r["unit"], r["version"], p["k"]), {})
            acc[cell].append(int(d.get("R") == g))
    return {k: (float(np.mean(v)), len(v)) for k, v in sorted(acc.items())}


FLOOR_MIN = 0.90
# Threshold candidates for every system's dev operating point (plan 7.1), the same for all systems. Amended
# 2026-11-16 before the freeze (docs/iterations.md): the first grid had steps of 0.005 only, but the API judges'
# log-probability scores lie much closer to 0 and 1 (for example 0.0002), so their best thresholds fell between grid
# points; all of them stopped at 0.005. Now: steps of 0.001, plus 1, 1.5, 2, ..., 9 x 10^-2 ... 10^-12 near 0 and
# the mirror values near 1 (1,183 candidates; a denser grid changes no chosen system by more than 0.003 on dev).
_DENSE = [m * 10.0 ** -e for e in range(2, 13) for m in (1, 1.5, 2, 3, 4, 5, 6, 7, 8, 9)]
GRID = np.unique(np.round(np.concatenate([np.linspace(0, 1, 1001), _DENSE, [1 - x for x in _DENSE]]), 13))


def decide(scores, th_s, th_r):
    """Scores {(unit, version, k): {"S": P(stop), "R": P(respond)}} -> decisions at thresholds (th_s, th_r)."""
    out = {}
    for key, sc in scores.items():
        d = {}
        if sc.get("S") is not None:
            d["S"] = "stop" if sc["S"] >= th_s else "continue"
        if sc.get("R") is not None:
            d["R"] = "respond" if sc["R"] >= th_r else "not"
        out[key] = d
    return out


def operating_point(rows, scores, grid=None, exclude=None):
    """Plan 7.1 operating point on dev: over a grid of (th_s, th_r), every floor kind >= FLOOR_MIN, then the highest
    five-part mean; if no setting meets the floors, the setting whose lowest floor is highest (ties: higher primary).
    A missing score counts as wrong. Returns the chosen thresholds and the metrics there."""
    exclude = excluded_units() if exclude is None else exclude
    grid = GRID if grid is None else np.asarray(grid)
    G = len(grid)
    units = defaultdict(lambda: {"S": np.ones(G, bool), "R": np.ones(G, bool)})
    meta, floor_pts = {}, defaultdict(list)
    for r in rows:
        if r["unit"] in exclude:
            continue
        u = units[r["unit"]]
        meta[r["unit"]] = (r["part"], r["subset"], r["spec"].get("which") if r["part"] == "floor" else None)
        for p in r["points"]:
            sc = scores.get((r["unit"], r["version"], p["k"]), {})
            g = p["gold"]
            ok_s = np.ones(G, bool) if g.get("S") is None else (
                np.zeros(G, bool) if sc.get("S") is None else
                ((sc["S"] >= grid) if g["S"] == "stop" else (sc["S"] < grid)))
            ok_r = np.ones(G, bool) if g.get("R") is None else (
                np.zeros(G, bool) if sc.get("R") is None else
                ((sc["R"] >= grid) if g["R"] == "respond" else (sc["R"] < grid)))
            u["S"] &= ok_s
            u["R"] &= ok_r
            if r["part"] == "floor":
                floor_pts[meta[r["unit"]][2].split("_")[0]].append((ok_s, ok_r))
    part_acc = {}
    for p in PARTS:
        us = [u for uid, u in units.items() if meta[uid][0] == p and meta[uid][1] is None]
        if us:
            part_acc[p] = np.mean([np.outer(u["S"], u["R"]) for u in us], 0)
    primary = np.mean([part_acc[p] for p in PARTS if p in part_acc], 0)
    floors = {k: np.mean([np.outer(a, b) for a, b in v], 0) for k, v in floor_pts.items()}
    low = np.min(np.stack(list(floors.values())), 0) if floors else np.ones((G, G))
    ok = low >= FLOOR_MIN
    if ok.any():
        val = np.where(ok, primary, -1.0)
        i, j = np.unravel_index(int(np.argmax(val)), val.shape)
        met = True
    else:                                            # lowest floor first, then primary
        val = np.where(low >= low.max() - 1e-12, primary, -1.0)
        i, j = np.unravel_index(int(np.argmax(val)), val.shape)
        met = False
    return {"th_s": float(grid[i]), "th_r": float(grid[j]), "floors_met": bool(met),
            "primary": float(primary[i, j]), "parts": {p: float(a[i, j]) for p, a in part_acc.items()},
            "floors": {k: float(a[i, j]) for k, a in floors.items()}, "lowest_floor": float(low[i, j])}


def _wmean(T, ids, w, sel):
    idx = [i for i, u in enumerate(ids) if sel(T[u])]
    if not idx:
        return None
    wi = w[:, idx]
    return (wi * np.array([T[ids[i]]["right"] for i in idx])).sum(1) / np.maximum(wi.sum(1), 1e-9)


def _stat(T, ids, w, which):
    """Weighted statistic for the bootstrap: which = primary | part:<p> | audio."""
    if which == "primary":
        vals = [_wmean(T, ids, w, lambda u, p=p: u["part"] == p and u["subset"] is None) for p in PARTS]
        return np.mean([v for v in vals if v is not None], 0)
    if which.startswith("part:"):
        p = which[5:]
        return _wmean(T, ids, w, lambda u: u["part"] == p and u["subset"] is None)
    if which == "audio":
        vals = [_wmean(T, ids, w, lambda u, p=p: u["audio"] and u["subset"] is None and u["part"] == p)
                for p in ("r_hear", "s_move")]
        return np.mean(vals, 0)
    raise NotImplementedError(which)


def point_value(T, which):
    m = metrics(T)
    if which == "primary":
        return m["primary"]
    if which.startswith("part:"):
        return m["parts"][which[5:]]
    if which == "audio":
        return m["audio"]
    raise NotImplementedError(which)


FACTORS = ("conv", "event", "second")          # plan 7.1


def diff_variance(Ta, Tb, which="primary", B=2000, seed=1, factors=FACTORS):
    """Variance of (metric(a) - metric(b)) under the multi-way combination of `factors` (default: the plan's three).
    Ta, Tb: unit tables of the same units."""
    ids = sorted(set(Ta) & set(Tb))
    fac = {k: [Ta[u][k] for u in ids] for k in factors}
    rng = np.random.default_rng(seed)

    def var_by(keys):
        labels = ["|".join(str(fac[k][i]) for k in keys) for i in range(len(ids))]
        lv = {x: j for j, x in enumerate(sorted(set(labels)))}
        idx = np.array([lv[x] for x in labels])
        w = rng.poisson(1.0, (B, len(lv)))[:, idx].astype(float)
        return float(np.var(_stat(Ta, ids, w, which) - _stat(Tb, ids, w, which)))

    names = list(factors)
    one = {k: var_by([k]) for k in names}
    total = 0.0
    for r in range(1, len(names) + 1):
        for combo in itertools.combinations(names, r):
            total += (-1) ** (r + 1) * (one[combo[0]] if r == 1 else var_by(list(combo)))
    return max(total, max(one.values())), one


def interval(Ta, Tb, which="primary", B=2000, seed=1, factors=FACTORS):
    point = point_value(Ta, which) - point_value(Tb, which)
    v, one = diff_variance(Ta, Tb, which, B, seed, factors)
    se = float(np.sqrt(v))
    return {"point": point, "se": se, "ci95": [point - 1.96 * se, point + 1.96 * se],
            "one_way_se": {k: float(np.sqrt(x)) for k, x in one.items()}}


def calibrate(T, n_sim=50, B=400, seed=7, n_mc=4000):
    """Plan 7.1 calibration on the real unit structure: two simulations, each compared with the known spread of the
    estimated difference of the five-part mean.
    1. Independent units (system a right with p = 0.8, b with 0.75): the combined SE over the analytic SE must lie in
       0.9-1.25.
    2. Clustering by the main-event recording group only (a's log-odds 1.4 + 0.8 z, one z ~ N(0, 1) per group; b
       independent with p = 0.75): the mean combined SE over the Monte Carlo SD of the estimate (n_mc fresh draws of
       the group effects and outcomes; the known value) must lie within 20% (0.8-1.2). The ratio to the one-way
       event-cluster SE of the same bootstrap is reported as well."""
    rng = np.random.default_rng(seed)
    ids = [u for u in T if T[u]["part"] in PARTS and T[u]["subset"] is None]
    cols = [np.array([i for i, u in enumerate(ids) if T[u]["part"] == p]) for p in PARTS]
    cols = [c for c in cols if len(c)]
    evs = sorted({T[u]["event"] for u in ids})
    ev_of = np.array([evs.index(T[u]["event"]) for u in ids])

    def point(ra, rb):
        return np.mean([ra[..., c].mean(-1) - rb[..., c].mean(-1) for c in cols], 0)

    def p_clu(z):
        return 1 / (1 + np.exp(-(1.4 + 0.8 * z[..., ev_of])))

    z = rng.normal(0, 1, (n_mc, len(evs)))
    est = point((rng.random((n_mc, len(ids))) < p_clu(z)).astype(float),
                (rng.random((n_mc, len(ids))) < 0.75).astype(float))
    sd_mc = float(np.std(est))
    n = [len(c) for c in cols]
    analytic = float(np.sqrt(sum((0.8 * 0.2 + 0.75 * 0.25) / k for k in n) / len(n) ** 2))
    se_ind, se_clu, se_one = [], [], []
    for s in range(n_sim):
        zs = rng.normal(0, 1, len(evs))
        for kind in ("ind", "clu"):
            pa = np.full(len(ids), 0.8) if kind == "ind" else p_clu(zs)
            ra, rb = rng.random(len(ids)) < pa, rng.random(len(ids)) < 0.75
            a = {u: {**T[u], "right": int(ra[i])} for i, u in enumerate(ids)}
            b = {u: {**T[u], "right": int(rb[i])} for i, u in enumerate(ids)}
            v, one = diff_variance(a, b, "primary", B, seed + s)
            if kind == "ind":
                se_ind.append(np.sqrt(v))
            else:
                se_clu.append(np.sqrt(v))
                se_one.append(np.sqrt(one["event"]))
    r1 = float(np.mean(se_ind)) / analytic
    r2 = float(np.mean(se_clu)) / sd_mc
    return {"units": len(ids), "units_per_part": dict(zip([p for p in PARTS if any(T[u]["part"] == p for u in ids)],
                                                          n)),
            "event_groups": sum(not e.startswith("none:") for e in evs), "event_clusters": len(evs),
            "analytic_se_independent": analytic, "independent_ratio": r1,
            "monte_carlo_sd_clustered": sd_mc, "clustered_ratio_to_known": r2,
            "clustered_rms_ratio_to_known": float(np.sqrt(np.mean(np.square(se_clu)))) / sd_mc,
            "clustered_ratio_to_one_way_event": float(np.mean(np.array(se_clu) / np.array(se_one))),
            "n_sim": n_sim, "B": B, "n_mc": n_mc,
            "pass": 0.9 <= r1 <= 1.25 and 0.8 <= r2 <= 1.2}
